require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';define('RESUMEIQ_FUNCTIONS_ONLY',true);require_once __DIR__.'/index.php';require_once __DIR__.'/lib/temp_evidence.php';$pdo=db();$candidates=loadCandidateRecords();$jobs=$pdo->query('SELECT * FROM jobs ORDER BY title')->fetchAll();$candidateId=$_POST['candidate_id']??($candidates[0]['id']??'');$jobId=(int)($_POST['job_id']??($jobs[0]['id']??0));$result=null;$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){try{$candidate=null;foreach($candidates as $row)if($row['id']===$candidateId){$candidate=$row;break;}$job=null;foreach($jobs as $row)if((int)$row['id']===$jobId){$job=$row;break;}if(!$candidate||!$job)throw new RuntimeException('Choose a valid candidate and job.');$base=realpath(__DIR__.'/uploads');$path=realpath(__DIR__.'/uploads/'.$candidate['file']);if(!$base||!$path||!str_starts_with(strtolower($path),strtolower($base.DIRECTORY_SEPARATOR)))throw new RuntimeException('Resume file is unavailable.');$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$extraction=extractResumeText($path,$ext);if(trim($extraction['text']??'')==='')throw new RuntimeException($extraction['error']?:'No usable resume text extracted.');$result=tempEvidenceAnalysis($candidate,$job,$extraction['text'],$extraction);}catch(Throwable $e){$error=$e->getMessage();}}
