<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-flask"></i> Temporary isolated prototype</div><h1>Evidence ATS lab</h1><p>Read-only deterministic comparison. It does not update current ATS scores or candidate records.</p></div><span class="tag">AI: OFF</span></section><div class="notice"><i class="fa-solid fa-triangle-exclamation"></i> Experimental panel. Existing production analysis remains unchanged.</div><form class="panel lab-form" method="post"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><select class="control" name="candidate_id"><?php foreach($candidates as $c):$d=candidatePresentation($c);?><option value="<?=htmlspecialchars($c['id'])?>" <?=$candidateId===$c['id']?'selected':''?>><?=htmlspecialchars($d['name'].' · '.$d['role'])?></option><?php endforeach?></select><select class="control" name="job_id"><?php foreach($jobs as $j):?><option value="<?=$j['id']?>" <?=$jobId===$j['id']?'selected':''?>><?=htmlspecialchars(trim($j['title']))?></option><?php endforeach?></select><button class="btn btn-primary"><i class="fa-solid fa-microscope"></i>Run evidence analysis</button></form><?php if($error):?><div class="notice"><?=htmlspecialchars($error)?></div><?php endif?>
<?php if($result):?><section class="lab-grid"><aside><article class="panel box"><div class="score"><?=$result['score']['total']?>/100</div><p>Deterministic evidence score</p><div class="break"><?php foreach($result['score']['breakdown'] as $key=>$value):$max=$result['score']['maximum'][$key];?><div><small><?=htmlspecialchars(ucwords(str_replace('_',' ',$key)))?> · <?=$value?>/<?=$max?></small><div class="bar"><i style="width:<?=round($value/$max*100)?>%"></i></div></div><?php endforeach?></div></article><article class="panel box" style="margin-top:10px"><h3>Review flags</h3><?php foreach($result['flags'] as $flag):?><p class="bad"><i class="fa-solid fa-flag"></i> <?=htmlspecialchars($flag)?></p><?php endforeach?><?php if(!$result['flags']):?><p class="good">No rule-based flags.</p><?php endif?></article></aside><main><article class="panel box"><h2>Requirement evidence</h2><?php foreach($result['matches'] as $m):?><div class="match"><strong><?=htmlspecialchars($m['requirement'])?></strong><span class="<?=$m['status']==='missing'?'bad':'good'?>"><?=htmlspecialchars(str_replace('_',' ',$m['status']))?></span><span><?=htmlspecialchars(implode(', ',$m['evidence'])?:'No evidence')?><?=$m['experience_evidence']?' · experience-backed':''?></span><b><?=round($m['confidence']*100)?>%</b></div><?php endforeach?><?php if(!$result['matches']):?><div class="empty">This job has no configured required skills.</div><?php endif?></article><article class="panel box" style="margin-top:10px"><h2>Debug / audit</h2><details open><summary>Structured result JSON</summary><pre><?=htmlspecialchars(json_encode(array_diff_key($result['parser'],['raw_text'=>1,'normalized_text'=>1])+['contact'=>$result['contact'],'sections'=>array_keys($result['sections']),'skills'=>$result['skills'],'timeline'=>$result['timeline'],'overlaps'=>$result['overlaps'],'matches'=>$result['matches'],'score'=>$result['score'],'flags'=>$result['flags'],'ai_status'=>$result['ai_status']],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre></details><details><summary>Detected sections</summary><pre><?=htmlspecialchars(json_encode($result['sections'],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre></details><details><summary>Normalized text</summary><pre><?=htmlspecialchars($result['parser']['normalized_text'])?></pre></details><details><summary>Raw extracted text</summary><pre><?=htmlspecialchars($result['parser']['raw_text'])?></pre></details></article></main></section><?php endif?><?php require __DIR__.'/views/partials/footer.php';?>
